#include <string.h>
#include <math.h>
#include "kneil_tinyml.h"
#include "kneil_model.h"   /* generated by emlearn: kneil_model_predict_proba() */

#if KNEIL_FS_HZ != KNEIL_MODEL_FS_HZ
#error "KNEIL_FS_HZ differs from the rate the model was trained for: re-export with pipeline/export_v4.py"
#endif

#ifndef KNEIL_MODEL_LOWPASS_HZ
#define KNEIL_MODEL_LOWPASS_HZ 0      /* models exported before the low-pass option */
#endif

/* Stairs evidence rule (owner decision, step E): keep stairs only with a large enough vote share. */
int kneil_stairs_rule(int raw_class, float vote)
{
	if ((raw_class == KNEIL_STAIRS_UP || raw_class == KNEIL_STAIRS_DOWN) && vote < KNEIL_MODEL_STAIRS_MIN_VOTE)
		return KNEIL_WALKING;
	return raw_class;
}

int kneil_classifier_raw_class(const kneil_classifier_t *c) { return c->raw_class; }
float kneil_classifier_vote(const kneil_classifier_t *c) { return c->vote; }

void kneil_classifier_proba(const kneil_classifier_t *c, float *out)
{
	for (int i = 0; i < KNEIL_N_CLASSES; i++) out[i] = c->proba[i];
}

void kneil_classifier_init(kneil_classifier_t *c)
{
	memset(c, 0, sizeof(*c));
	c->last_class = -1;
	c->raw_class = -1;
#if KNEIL_MODEL_LOWPASS_HZ > 0
	for (int k = 0; k < 3; k++)
		kneil_lowpass_design(&c->lp[k], (float)KNEIL_FS_HZ, (float)KNEIL_MODEL_LOWPASS_HZ);
#endif
}

int kneil_classifier_push(kneil_classifier_t *c, float ax, float ay, float az)
{
	/* per sample: store only (plus the input low-pass if the model was trained with one) */
#if KNEIL_MODEL_LOWPASS_HZ > 0
	ax = kneil_lowpass_step(&c->lp[0], ax); ay = kneil_lowpass_step(&c->lp[1], ay); az = kneil_lowpass_step(&c->lp[2], az);
#endif
	c->x[c->count] = ax; c->y[c->count] = ay; c->z[c->count] = az;
	c->count++;
	c->since_hop++;
	if (c->count < KNEIL_WIN_N || c->since_hop < KNEIL_HOP_N) return -1;

	kneil_features(c->x, c->y, c->z, KNEIL_WIN_N, (float)KNEIL_FS_HZ, c->feat);

	/* class probabilities of the ensemble (forest: vote shares; single tree: one-hot), then argmax (ties: lowest id) */
	kneil_model_predict_proba(c->feat, KNEIL_N_FEATURES, c->proba, KNEIL_N_CLASSES);
	int raw = 0;
	for (int i = 1; i < KNEIL_N_CLASSES; i++)
		if (c->proba[i] > c->proba[raw]) raw = i;
	c->raw_class = raw;
	c->vote = c->proba[raw];
	const int cls = kneil_stairs_rule(raw, c->vote);

	/* magnitude history (4 s), updated once per hop with the newest samples of the window */
	const int n_new = (c->hist_count == 0) ? KNEIL_WIN_N : KNEIL_HOP_N;
	if (c->hist_count + n_new > KNEIL_HIST_N) {
		const int drop = c->hist_count + n_new - KNEIL_HIST_N;
		memmove(c->mhist, c->mhist + drop, (size_t)(c->hist_count - drop) * sizeof(float));
		c->hist_count -= drop;
	}
	for (int i = KNEIL_WIN_N - n_new; i < KNEIL_WIN_N; i++)
		c->mhist[c->hist_count++] = sqrtf(c->x[i] * c->x[i] + c->y[i] * c->y[i] + c->z[i] * c->z[i]);
	c->last_stride_s = (cls == KNEIL_WALKING || cls == KNEIL_STAIRS_UP || cls == KNEIL_STAIRS_DOWN)
		? kneil_stride_period(c->mhist, c->hist_count, (float)KNEIL_FS_HZ) : 0.0f;

	const int keep = KNEIL_WIN_N - KNEIL_HOP_N;
	memmove(c->x, c->x + KNEIL_HOP_N, (size_t)keep * sizeof(float));
	memmove(c->y, c->y + KNEIL_HOP_N, (size_t)keep * sizeof(float));
	memmove(c->z, c->z + KNEIL_HOP_N, (size_t)keep * sizeof(float));
	c->count = keep;
	c->since_hop = 0;
	c->last_class = cls;
	return cls;
}
